220:
[
  {
    "q": "《魔法帽的工作室》的作者是誰？",
    "a": "白濱鷗（白浜鴎）。"
  },
  {
    "q": "主角可可（Coco）在誤用魔法前，原本是什麼身份？",
    "a": "裁縫店老闆的女兒（普通人類/不知者）。"
  },
  {
    "q": "收可可為徒、引領她進入魔法世界的魔法師叫什麼名字？",
    "a": "基弗利（Qifrey）。"
  },
  {
    "q": "在這個故事的世界觀中，施展魔法的核心工具與媒介是什麼？",
    "a": "魔墨（魔法墨水）與魔法陣（透過繪製來施法）。"
  },
  {
    "q": "故事中反派組織「寬帽（つばあり）」的主要主張與目的是什麼？",
    "a": "反對現行魔法體制的禁令，主張自由使用被禁止的「肉體改造」等禁忌魔法。"
  }
]
